def transform(grid):
    """Connect consecutive marker cells with color 3 along shared rows or columns."""
    from collections import Counter
    g = [row[:] for row in grid]
    counts = Counter(x for row in g for x in row)
    bg = counts.most_common(1)[0][0]
    h, w = len(g), len(g[0])
    markers = [c for c in counts if c != bg]
    for color in markers:
        for r in range(h):
            xs = [c for c in range(w) if g[r][c] == color]
            for a, b in zip(xs, xs[1:]):
                for c in range(a + 1, b):
                    if g[r][c] == bg:
                        g[r][c] = 3
        for c in range(w):
            ys = [r for r in range(h) if g[r][c] == color]
            for a, b in zip(ys, ys[1:]):
                for r in range(a + 1, b):
                    if g[r][c] == bg:
                        g[r][c] = 3
    return g
